// dusrelpdf — Android library (AAR) wrapping the UniFFI Kotlin bindings.
//
// Maven coordinates: io.github.dusmamud:dusrelpdf:0.1.0
//
// The Kotlin source compiled here is the UniFFI-generated file at
// bindings/kotlin/uniffi/ — the single source of truth, regenerated by
// scripts/regenerate-uniffi.sh. It is registered as a source root (below)
// instead of being copied, so the module can never drift from the
// generated file.
//
// The native library (libdusrelpdf_uniffi.so) is NOT committed — see
// README.md for how to build it with cargo-ndk into src/main/jniLibs/.

plugins {
    id("com.android.library")
    id("org.jetbrains.kotlin.android")
    id("maven-publish")
}

group = "io.github.dusmamud"
version = "0.1.0"

android {
    namespace = "io.github.dusmamud.dusrelpdf"
    compileSdk = 34

    defaultConfig {
        minSdk = 21
        consumerProguardFiles("consumer-rules.pro")
    }

    compileOptions {
        sourceCompatibility = JavaVersion.VERSION_1_8
        targetCompatibility = JavaVersion.VERSION_1_8
    }

    kotlinOptions {
        jvmTarget = "1.8"
    }

    // Generated UniFFI Kotlin lives at bindings/kotlin/uniffi/ (one
    // directory up from this module). Register it as a source root:
    // package uniffi.dusrelpdf_uniffi resolves from that directory.
    // If AGP ever rejects a source dir outside the module, the fallback is
    // a Copy task into build/generated/source/uniffi (see README.md).
    sourceSets {
        getByName("main") {
            java.srcDirs("src/main/java", "../uniffi")
        }
    }

    publishing {
        singleVariant("release") {
            withSourcesJar()
            withJavadocJar()
        }
    }
}

dependencies {
    // JNA is the FFI runtime the generated bindings call into (UniFFI
    // Kotlin requires JNA >= 5.12.0). It is `api`, not `implementation`,
    // on purpose: the generated code references com.sun.jna.* directly,
    // so consumers of this AAR need JNA on their compile/runtime
    // classpath transitively — with `implementation` they would hit
    // NoClassDefFoundError at first use. The @aar variant is the
    // Android-specific packaging (JNA's own native libs included).
    api("net.java.dev.jna:jna:5.14.0@aar")
}

// Maven Central publication. NOT run automatically.
//  - Smoke test locally:   ./gradlew :dusrelpdf:publishToMavenLocal
//    (checks the POM + AAR build; installs into ~/.m2 only)
//  - Real release: Sonatype Central + GPG signing, wired by the release
//    workflow at release time (see README.md). Nothing is published here.
afterEvaluate {
    publishing {
        publications {
            create<MavenPublication>("release") {
                groupId = "io.github.dusmamud"
                artifactId = "dusrelpdf"
                version = "0.1.0"

                from(components["release"])

                pom {
                    name.set("dusrelpdf")
                    description.set("Offline PDF toolkit for Android — merge, split, extract, remove, reorder, rotate, images-to-PDF, watermark, page numbers, signature-image placement. Rust core, UniFFI Kotlin bindings.")
                    url.set("https://github.com/dusmamud/dusrelpdf")

                    licenses {
                        license {
                            name.set("MIT License")
                            url.set("https://opensource.org/licenses/MIT")
                        }
                    }
                    developers {
                        developer {
                            id.set("dusmamud")
                            name.set("dusmamud")
                            url.set("https://github.com/dusmamud")
                        }
                    }
                    scm {
                        connection.set("scm:git:https://github.com/dusmamud/dusrelpdf.git")
                        developerConnection.set("scm:git:ssh://github.com/dusmamud/dusrelpdf.git")
                        url.set("https://github.com/dusmamud/dusrelpdf")
                    }
                }
            }
        }
    }
}
